import { api, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/sections/';
export const sectionApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listSections: build.query({
            query: ({ project, block }) => {
                const params = new URLSearchParams();
                if (project !== undefined && project !== null && project !== '')
                    params.append('project', Number(project).toString());
                if (block !== undefined && block !== null && block !== '')
                    params.append('block', Number(block).toString());
                params.append('without_pagination', '1');
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: ['SECTION'],
        }),
        listAllSections: build.query({
            query: () => ({
                url: urlUtils(API_PATH, `?without_pagination=1`),
            }),
            providesTags: ['SECTION'],
        }),
        addSections: build.mutation({
            query(data) {
                return {
                    url: API_PATH,
                    method: 'POST',
                    body: data,
                };
            },
            invalidatesTags: ['SECTION'],
        }),
        updateSections: build.mutation({
            query(data) {
                return {
                    url: data.block_key ? `${API_PATH}${data.block_key}` : API_PATH,
                    method: 'PUT',
                    body: data,
                };
            },
            invalidatesTags: ['SECTION'],
        }),
        deleteSectionType: build.mutation({
            query(id) {
                return {
                    url: `${API_PATH}${id}`,
                    method: 'DELETE',
                };
            },
            invalidatesTags: ['SECTION'],
        }),
    }),
});
export const { useListSectionsQuery, useListAllSectionsQuery, useAddSectionsMutation, useUpdateSectionsMutation, useDeleteSectionTypeMutation, } = sectionApi;
